// Builds public/_redirects from migration/url-inventory.csv plus catch-all rules for the old WordPress site.
// Run: node scripts/build-redirects.mjs   (re-run after editing the CSV)
import { readFileSync, writeFileSync } from 'node:fs';

const csv = readFileSync(new URL('../migration/url-inventory.csv', import.meta.url), 'utf8').trim().split('\n');
const header = csv.shift().split(',');
const col = (name) => header.indexOf(name);

const lines = [
  '# Generated by scripts/build-redirects.mjs from migration/url-inventory.csv. Do not edit by hand.',
  '',
  '# Old WordPress URLs with backlinks (most-linked first)',
];
const seen = new Set();
for (const row of csv) {
  const f = row.split(',');
  const from = f[col('old_path')];
  const to = f[col('new_path')];
  if (from === '/' || from === to || seen.has(from)) continue;
  seen.add(from);
  lines.push(`${from} ${to} 301`);
  // Some links omit the trailing slash; send those straight to the final URL instead of chaining.
  if (from.endsWith('/') && from.length > 1) lines.push(`${from.slice(0, -1)} ${to} 301`);
}

lines.push(
  '',
  '# Everything else from the old site',
  '/coupons/* /deals/ 301',
  '/cbd-coupons/* /deals/ 301',
  '/shop/* /deals/ 301',
  '/subscription-boxes/* /deals/ 301',
  '/headshop-reviews/* /deals/ 301',
  '/cbd-oil-reviews/* /brands/ 301',
  '/blog/* /guides/ 301',
  '/category/* /guides/ 301',
  '/tag/* /guides/ 301',
  '/author/* / 301',
  '/page/* / 301',
  '/feed/* / 301',
  '/comments/feed/* / 301',
  '/wp-content/* / 301',
  '/wp-admin/* / 301',
  '/wp-login.php / 301',
  '/xmlrpc.php / 301',
  '/sitemap_index.xml /sitemap-index.xml 301',
  '/post-sitemap.xml /sitemap-index.xml 301',
  '/page-sitemap.xml /sitemap-index.xml 301',
  '',
);

writeFileSync(new URL('../public/_redirects', import.meta.url), lines.join('\n'));
console.log(`Wrote ${lines.filter((l) => l && !l.startsWith('#')).length} rules to public/_redirects`);
